BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "customer" (
	"no"	INTEGER,
	"customer_id"	TEXT,
	"customer_name"	TEXT,
	"supplier_id"	TEXT,
	"selling_price_per_kg"	INTEGER,
	"effective_date"	TEXT,
	"payment_term"	TEXT
);
CREATE TABLE IF NOT EXISTS "deliveries" (
	"no"	INTEGER,
	"date"	TEXT,
	"week"	TEXT,
	"month"	TEXT,
	"delivery_id"	TEXT,
	"delivery_ref"	TEXT,
	"supplier_id"	TEXT,
	"customer_id"	TEXT,
	"loading_port_id"	TEXT,
	"qty_kg"	INTEGER
);
CREATE TABLE IF NOT EXISTS "gross_profit" (
	"month"	TEXT,
	"region"	TEXT,
	"loading_port_id"	TEXT,
	"supplier_id"	TEXT,
	"customer_id"	TEXT,
	"delivery_code"	TEXT,
	"material_price_per_kg"	INTEGER,
	"trucking_cost_per_kg"	INTEGER,
	"freight_per_kg"	INTEGER,
	"total_cost_per_kg"	INTEGER,
	"sales_price_per_kg"	INTEGER,
	"unit_profit_per_kg"	INTEGER,
	"qty_delivered_kg"	INTEGER,
	"total_gross_profit"	INTEGER
);
CREATE TABLE IF NOT EXISTS "purchasing_history" (
	"no"	INTEGER,
	"date"	TEXT,
	"transaction_id"	TEXT,
	"supplier_id"	TEXT,
	"unit_price_per_kg"	INTEGER,
	"qty_kg"	INTEGER,
	"total_amount"	INTEGER,
	"amount_paid"	INTEGER,
	"delivered"	INTEGER,
	"outstanding_deposit_kg"	INTEGER,
	"outstanding_amount"	INTEGER
);
CREATE TABLE IF NOT EXISTS "supplier" (
	"no"	INTEGER,
	"supplier_id"	TEXT,
	"supplier_name"	TEXT,
	"region"	TEXT,
	"port_id"	TEXT,
	"buying_price_per_kg"	INTEGER,
	"effective_from"	TEXT,
	"effective_to"	TEXT
);
COMMIT;
